namespace sv_4bf7b7d9285d4644833a3f08760d5481.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service that holds the currently selected warehouse and notifies
/// subscribers when the selection changes.  Scoped lifetime ensures each
/// Blazor Server circuit (i.e. each browser tab / user) gets its own instance.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new() { Id = "wh-1", Name = "Warehouse A" },
        new() { Id = "wh-2", Name = "Warehouse B" },
        new() { Id = "wh-3", Name = "Warehouse C" },
    ];

    private WarehouseInfo _current = AvailableWarehouses[0];

    public WarehouseInfo Current => _current;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = AvailableWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse is null || warehouse.Id == _current.Id)
            return;

        _current = warehouse;
        OnChange?.Invoke();
    }
}

namespace sv_4bf7b7d9285d4644833a3f08760d5481.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Components call <see cref="RefreshAsync"/> to poll for new data;
/// when the count changes ALL subscribers are notified via <see cref="OnAlertCountChanged"/>.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentAlertCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Polls for new data and notifies all subscribers if the count changed.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        var count = await GetLowStockCountAsync(warehouseId);
        CurrentAlertCount = count;
        OnAlertCountChanged?.Invoke();
    }
}

