@page "/dashboard"
@using sv_4bf7b7d9285d4644833a3f08760d5481.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IAsyncDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard – @WarehouseState.Current.Name</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@WarehouseState.Current.Name</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body d-flex align-items-center">
        <h5 class="card-title mb-0">Low-Stock Alerts</h5>
        <AlertBadge @rendermode="InteractiveServer" />
    </div>
    <div class="card-footer text-muted">
        Refreshes every 10 seconds while this page is open.
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;

    protected override async Task OnInitializedAsync()
    {
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            // Warehouse changed — restart polling with new warehouse
            await RestartPollingAsync();
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseHandler;

        await StartPollingAsync();
    }

    private async Task StartPollingAsync()
    {
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        // Initial fetch so we don't wait 10 seconds for the first value
        await AlertService.RefreshAsync(WarehouseState.Current.Id);

        _ = PollLoopAsync(token);
    }

    private async Task PollLoopAsync(CancellationToken token)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(token))
            {
                await InvokeAsync(async () =>
                {
                    await AlertService.RefreshAsync(WarehouseState.Current.Id);
                });
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task RestartPollingAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
        await StartPollingAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

